{
  "name": "ACQ400/ACQ2106模块化数据采集机箱",
  "name_en": "ACQ400/ACQ2106 modular data acquisition chassis",
  "manufacturer": "D-TACQ",
  "description": "这是一类面向实验室瞬态记录与多通道测量的模块化数据采集机箱，可搭载多个采集站点或功能模块，通过网络输出通道原始数据、状态信息和校准数据，并支持同步、分段采集以及部分数字/波形输出功能。",
  "description_en": "This is a family of modular data acquisition chassis for laboratory transient recording and multi-channel measurement. It can host multiple acquisition sites or functional modules, provide channel raw data, status, and calibration information over the network, and supports synchronization, segmented acquisition, and some digital or waveform output functions.",
  "tag_hints": [
    "modular DAQ",
    "high-speed digitizer",
    "transient recording",
    "multi-channel acquisition",
    "Ethernet data acquisition",
    "segmented acquisition",
    "synchronization routing",
    "calibration scaling"
  ],
  "actions": [
    {
      "action_name": "read",
      "description": "读取单个通道的采集后数据。",
      "description_en": "Read post-shot data from a single channel."
    },
    {
      "action_name": "get_blocks",
      "description": "按数据块获取已记录的通道数据。",
      "description_en": "Fetch recorded channel data in blocks."
    },
    {
      "action_name": "st_monitor",
      "description": "监视设备状态通道与事件变化。",
      "description_en": "Monitor the device status channel and state events."
    },
    {
      "action_name": "get_state",
      "description": "获取当前采集状态。",
      "description_en": "Get the current acquisition state."
    },
    {
      "action_name": "get_pre",
      "description": "获取预触发样本数。",
      "description_en": "Get the pre-trigger sample count."
    },
    {
      "action_name": "get_post",
      "description": "获取后触发样本数。",
      "description_en": "Get the post-trigger sample count."
    },
    {
      "action_name": "get_total",
      "description": "获取总样本数。",
      "description_en": "Get the total sample count."
    },
    {
      "action_name": "get_elapsed",
      "description": "获取已采集样本数。",
      "description_en": "Get the elapsed sample count."
    },
    {
      "action_name": "wait_event",
      "description": "等待指定状态事件发生。",
      "description_en": "Wait for a specified state event."
    },
    {
      "action_name": "wait_armed",
      "description": "等待设备进入布防状态。",
      "description_en": "Wait for the device to become armed."
    },
    {
      "action_name": "wait_stopped",
      "description": "等待采集停止。",
      "description_en": "Wait for acquisition to stop."
    },
    {
      "action_name": "wait_state_changed",
      "description": "等待状态发生变化。",
      "description_en": "Wait for the state to change."
    },
    {
      "action_name": "init_site_client",
      "description": "初始化指定站点模块的访问。",
      "description_en": "Initialize access to a specified site module."
    },
    {
      "action_name": "make_sa_sd_aliases",
      "description": "为站点服务建立简写别名。",
      "description_en": "Create shorthand aliases for site services."
    },
    {
      "action_name": "get_sys_info",
      "description": "获取系统信息。",
      "description_en": "Get system information."
    },
    {
      "action_name": "close",
      "description": "关闭与设备的连接。",
      "description_en": "Close the connection to the device."
    },
    {
      "action_name": "state",
      "description": "获取当前状态。",
      "description_en": "Get the current state."
    },
    {
      "action_name": "post_samples",
      "description": "获取后触发样本数。",
      "description_en": "Get the post-trigger sample count."
    },
    {
      "action_name": "pre_samples",
      "description": "获取预触发样本数。",
      "description_en": "Get the pre-trigger sample count."
    },
    {
      "action_name": "elapsed_samples",
      "description": "获取已采集样本数。",
      "description_en": "Get the elapsed sample count."
    },
    {
      "action_name": "demux_status",
      "description": "获取数据解复用状态。",
      "description_en": "Get the data demultiplexing status."
    },
    {
      "action_name": "samples",
      "description": "获取总样本数。",
      "description_en": "Get the total sample count."
    },
    {
      "action_name": "get_aggregator_sites",
      "description": "获取聚合采集涉及的站点列表。",
      "description_en": "Get the list of sites used by the aggregator."
    },
    {
      "action_name": "get_aggregator_svc_list",
      "description": "获取聚合采集的服务列表。",
      "description_en": "Get the aggregator service list."
    },
    {
      "action_name": "fetch_all_calibration",
      "description": "获取全部校准数据。",
      "description_en": "Fetch all calibration data."
    },
    {
      "action_name": "scale_raw",
      "description": "将原始计数按校准系数缩放。",
      "description_en": "Scale raw counts using calibration data."
    },
    {
      "action_name": "chan2volts",
      "description": "将指定通道原始数据换算为电压。",
      "description_en": "Convert raw data from a specified channel to volts."
    },
    {
      "action_name": "read_chan",
      "description": "读取指定通道的数据。",
      "description_en": "Read data from a specified channel."
    },
    {
      "action_name": "read_decims",
      "description": "读取抽取后的数据。",
      "description_en": "Read decimated data."
    },
    {
      "action_name": "nchan",
      "description": "获取采集通道数。",
      "description_en": "Get the number of acquisition channels."
    },
    {
      "action_name": "data_size",
      "description": "获取记录数据大小。",
      "description_en": "Get the recorded data size."
    },
    {
      "action_name": "uut_demux_enabled",
      "description": "获取设备端是否启用解复用。",
      "description_en": "Get whether on-device demultiplexing is enabled."
    },
    {
      "action_name": "read_transient_timebase",
      "description": "读取瞬态采集的时间基准信息。",
      "description_en": "Read timebase information for transient acquisition."
    },
    {
      "action_name": "load_segments",
      "description": "加载分段采集配置。",
      "description_en": "Load segmented acquisition configuration."
    },
    {
      "action_name": "show_segments",
      "description": "查看分段采集配置。",
      "description_en": "Show segmented acquisition configuration."
    },
    {
      "action_name": "clear_counters",
      "description": "清除计数器。",
      "description_en": "Clear counters."
    },
    {
      "action_name": "set_sync_routing_master",
      "description": "设置同步路由为主设备模式。",
      "description_en": "Set synchronization routing for master mode."
    },
    {
      "action_name": "set_sync_routing_slave",
      "description": "设置同步路由为从设备模式。",
      "description_en": "Set synchronization routing for slave mode."
    },
    {
      "action_name": "set_sync_routing",
      "description": "设置同步路由。",
      "description_en": "Set synchronization routing."
    },
    {
      "action_name": "set_mb_clk",
      "description": "设置机箱主时钟。",
      "description_en": "Set the chassis main clock."
    },
    {
      "action_name": "load_stl",
      "description": "加载STL时序序列。",
      "description_en": "Load an STL timing sequence."
    },
    {
      "action_name": "load_gpg",
      "description": "加载GPG模式发生器程序。",
      "description_en": "Load a GPG pattern generator program."
    },
    {
      "action_name": "load_dpg",
      "description": "加载DPG模式发生器程序。",
      "description_en": "Load a DPG pattern generator program."
    },
    {
      "action_name": "load_wrpg",
      "description": "加载WRPG程序。",
      "description_en": "Load a WRPG program."
    },
    {
      "action_name": "load_dio482pg",
      "description": "加载DIO482模式发生器程序。",
      "description_en": "Load a DIO482 pattern generator program."
    },
    {
      "action_name": "set_DO",
      "description": "设置数字输出状态。",
      "description_en": "Set the digital output state."
    },
    {
      "action_name": "load_awg",
      "description": "加载任意波形发生器波形或程序。",
      "description_en": "Load an arbitrary waveform generator waveform or program."
    },
    {
      "action_name": "set_segment",
      "description": "设置单个采集分段参数。",
      "description_en": "Set parameters for an acquisition segment."
    },
    {
      "action_name": "run_service",
      "description": "启动设备上的指定服务。",
      "description_en": "Run a specified service on the device."
    }
  ]
}

